mkuse!{use std :: collections :: BTreeMap ;}
mkuse!{use rustc_data_structures :: fx :: FxIndexSet ;}
mkuse!{use rustc_errors :: Diag ;}
mkuse!{use rustc_middle :: ty :: RegionVid ;}
mkuse!{use smallvec :: SmallVec ;}
mkuse!{use tracing :: debug ;}
mkuse!{use super :: { ErrorConstraintInfo , RegionName , RegionNameSource } ;}
mkuse!{use crate :: MirBorrowckCtxt ;}
mkitem!{mkenum!{# [doc = " The different things we could suggest."] enum SuggestedConstraint { # [doc = " Outlives(a, [b, c, d, ...]) => 'a: 'b + 'c + 'd + ..."] Outlives (RegionName , SmallVec < [RegionName ; 2] >) , # [doc = " 'a = 'b"] Equal (RegionName , RegionName) , # [doc = " 'a: 'static i.e. 'a = 'static and the user should just use 'static"] Static (RegionName) , }}}
mkitem!{mkstruct!{# [doc = " Collects information about outlives constraints that needed to be added for a given MIR node"] # [doc = " corresponding to a function definition."] # [doc = ""] # [doc = " Adds a help note suggesting adding a where clause with the needed constraints."] # [derive (Default)] pub (crate) struct OutlivesSuggestionBuilder { # [doc = " The list of outlives constraints that need to be added. Specifically, we map each free"] # [doc = " region to all other regions that it must outlive. I will use the shorthand `fr:"] # [doc = " outlived_frs`. Not all of these regions will already have names necessarily. Some could be"] # [doc = " implicit free regions that we inferred. These will need to be given names in the final"] # [doc = " suggestion message."] constraints_to_add : BTreeMap < RegionVid , Vec < RegionVid > > , }}}
mkitem!{mkimpl!{impl OutlivesSuggestionBuilder { # [doc = " Returns `true` iff the `RegionNameSource` is a valid source for an outlives"] # [doc = " suggestion."] fn region_name_is_suggestable (name : & RegionName) -> bool { match name . source { RegionNameSource :: NamedEarlyParamRegion (..) | RegionNameSource :: NamedLateParamRegion (..) | RegionNameSource :: Static => true , RegionNameSource :: SynthesizedFreeEnvRegion (..) | RegionNameSource :: AnonRegionFromArgument (..) | RegionNameSource :: AnonRegionFromUpvar (..) | RegionNameSource :: AnonRegionFromOutput (..) | RegionNameSource :: AnonRegionFromYieldTy (..) | RegionNameSource :: AnonRegionFromAsyncFn (..) | RegionNameSource :: AnonRegionFromImplSignature (..) => { debug ! ("Region {:?} is NOT suggestable" , name) ; false } } } # [doc = " Returns a name for the region if it is suggestable. See `region_name_is_suggestable`."] fn region_vid_to_name (& self , mbcx : & MirBorrowckCtxt < '_ , '_ , '_ > , region : RegionVid ,) -> Option < RegionName > { mbcx . give_region_a_name (region) . filter (Self :: region_name_is_suggestable) } # [doc = " Compiles a list of all suggestions to be printed in the final big suggestion."] fn compile_all_suggestions (& self , mbcx : & MirBorrowckCtxt < '_ , '_ , '_ > ,) -> SmallVec < [SuggestedConstraint ; 2] > { let mut suggested = SmallVec :: new () ; let mut unified_already = FxIndexSet :: default () ; for (fr , outlived) in & self . constraints_to_add { let Some (fr_name) = self . region_vid_to_name (mbcx , * fr) else { continue ; } ; let outlived = outlived . iter () . filter_map (| fr | self . region_vid_to_name (mbcx , * fr) . map (| rname | (fr , rname))) . collect :: < Vec < _ > > () ; if outlived . is_empty () { continue ; } if outlived . iter () . any (| (_ , outlived_name) | matches ! (outlived_name . source , RegionNameSource :: Static)) { suggested . push (SuggestedConstraint :: Static (fr_name)) ; } else { let (unified , other) : (Vec < _ > , Vec < _ >) = outlived . into_iter () . partition (| (r , _) | { self . constraints_to_add . get (r) . is_some_and (| r_outlived | r_outlived . as_slice () . contains (fr)) } ,) ; for (r , bound) in unified . into_iter () { if ! unified_already . contains (fr) { suggested . push (SuggestedConstraint :: Equal (fr_name , bound)) ; unified_already . insert (r) ; } } if ! other . is_empty () { let other = other . iter () . map (| (_ , rname) | * rname) . collect :: < SmallVec < _ > > () ; suggested . push (SuggestedConstraint :: Outlives (fr_name , other)) } } } suggested } # [doc = " Add the outlives constraint `fr: outlived_fr` to the set of constraints we need to suggest."] pub (crate) fn collect_constraint (& mut self , fr : RegionVid , outlived_fr : RegionVid) { debug ! ("Collected {:?}: {:?}" , fr , outlived_fr) ; self . constraints_to_add . entry (fr) . or_default () . push (outlived_fr) ; } # [doc = " Emit an intermediate note on the given `Diag` if the involved regions are suggestable."] pub (crate) fn intermediate_suggestion (& mut self , mbcx : & MirBorrowckCtxt < '_ , '_ , '_ > , errci : & ErrorConstraintInfo < '_ > , diag : & mut Diag < '_ > ,) { let fr_name = self . region_vid_to_name (mbcx , errci . fr) ; let outlived_fr_name = self . region_vid_to_name (mbcx , errci . outlived_fr) ; if let (Some (fr_name) , Some (outlived_fr_name)) = (fr_name , outlived_fr_name) && ! matches ! (outlived_fr_name . source , RegionNameSource :: Static) { diag . help (format ! ("consider adding the following bound: `{fr_name}: {outlived_fr_name}`" ,)) ; } } # [doc = " If there is a suggestion to emit, add a diagnostic to the buffer. This is the final"] # [doc = " suggestion including all collected constraints."] pub (crate) fn add_suggestion (& self , mbcx : & mut MirBorrowckCtxt < '_ , '_ , '_ >) { if self . constraints_to_add . is_empty () { debug ! ("No constraints to suggest.") ; return ; } if self . constraints_to_add . len () == 1 && self . constraints_to_add . values () . next () . unwrap () . len () == 1 { debug ! ("Only 1 suggestion. Skipping.") ; return ; } let suggested = self . compile_all_suggestions (mbcx) ; if suggested . is_empty () { debug ! ("Only 1 suggestable constraint. Skipping.") ; return ; } let mut diag = if let [constraint] = suggested . as_slice () { mbcx . dcx () . struct_help (match constraint { SuggestedConstraint :: Outlives (a , bs) => { let bs : SmallVec < [String ; 2] > = bs . iter () . map (| r | r . to_string ()) . collect () ; format ! ("add bound `{a}: {}`" , bs . join (" + ")) } SuggestedConstraint :: Equal (a , b) => { format ! ("`{a}` and `{b}` must be the same: replace one with the other") } SuggestedConstraint :: Static (a) => format ! ("replace `{a}` with `'static`") , }) } else { let mut diag = mbcx . infcx . tcx . dcx () . struct_help ("the following changes may resolve your lifetime errors") ; for constraint in suggested { match constraint { SuggestedConstraint :: Outlives (a , bs) => { let bs : SmallVec < [String ; 2] > = bs . iter () . map (| r | r . to_string ()) . collect () ; diag . help (format ! ("add bound `{a}: {}`" , bs . join (" + "))) ; } SuggestedConstraint :: Equal (a , b) => { diag . help (format ! ("`{a}` and `{b}` must be the same: replace one with the other" ,)) ; } SuggestedConstraint :: Static (a) => { diag . help (format ! ("replace `{a}` with `'static`")) ; } } } diag } ; let mir_span = mbcx . body . span ; diag . sort_span = mir_span . shrink_to_hi () ; mbcx . buffer_non_error (diag) ; } }}}